```json
{
  "findings": [
    {
      "rule_id": "sql-injection",
      "severity": "error",
      "file": "src/login.js",
      "line": 8,
      "message": "findByUsername builds the SQL query via string concatenation with the user-controlled `username` value (`\"SELECT * FROM users WHERE username = '\" + username + \"' AND active = 1\"`), allowing SQL injection.",
      "suggestion": "Use a parameterized query / prepared statement, e.g. `db.query(\"SELECT * FROM users WHERE username = ? AND active = 1\", [username])`, and never concatenate untrusted input into SQL."
    },
    {
      "rule_id": "hardcoded-secret",
      "severity": "error",
      "file": "src/login.js",
      "line": 13,
      "message": "API key is hardcoded in source: `const SERVICE_API_KEY = \"sk-fixture-9f8e7d6c5b4a3f2e1d0c\";` and additionally exported, exposing the credential in the repository.",
      "suggestion": "Load the key from a secret manager or environment variable at runtime (e.g. `process.env.SERVICE_API_KEY`), rotate the leaked credential, and keep it out of version control."
    },
    {
      "rule_id": "xss",
      "severity": "error",
      "file": "src/render.js",
      "line": 5,
      "message": "User-controlled `user.bio` is assigned directly to `element.innerHTML`, enabling stored XSS that executes arbitrary script in the victim's browser.",
      "suggestion": "Render the value as text (`element.textContent = user.bio`) or sanitize it with a vetted HTML sanitizer before injecting it into the DOM."
    }
  ]
}
```

